import{z as B,x as s,o,c as p,q as r,j as E,D as t,d as l,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"SABR 对 LMM 校准","description":"","frontmatter":{"title":"SABR 对 LMM 校准","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sabr-lmm-calib.md","filePath":"quant/sabr-lmm-calib.md","lastUpdated":1791413859000}'),d={name:"quant/sabr-lmm-calib.md"};function m(M,a,u,h,S,b){const n=s("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="sabr-对-lmm-校准" tabindex="-1">SABR 对 LMM 校准 <a class="header-anchor" href="#sabr-对-lmm-校准" aria-label="Permalink to &quot;SABR 对 LMM 校准&quot;">​</a></h1><div class="epigraph"><p>每个 swaption 格子一个 SABR，只保证该格子的微笑；LMM 要的是整条远期曲线的动态同时重现这些微笑，而不能破坏远期之间的相关。</p><footer>—— Hagan, Kumar, Lesniewski and Woodward, Managing Smile Risk, Wilmott, 2002；Rebonato 对 LMM 校准的论述</footer></div><p><a href="/quant/caps-floors-swaptions">上一课</a>给出 cap 与 swaption 两张网。主干 <a href="/quant/sabr">SABR</a> 与 <a href="/quant/sabr-calib">SABR 校准</a>、<a href="/quant/lmm">LMM</a> 已分写。缺口是<strong>把微笑装进 LMM</strong>：不是再推 SABR 公式，而是期限结构模型如何吸收按格子校准的 \\(\\alpha,\\rho,\\nu\\)，以及为什么「每个互换一个 SABR」加不起来等于一个无套利 LMM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场习惯：对每个 \\((T_{\\mathrm{exp}},T_{\\mathrm{tenor}})\\) 的 swaption 拟合 SABR，得到该互换率的微笑。LMM 的状态是一向量远期 \\(L_i\\)，瞬时协方差决定所有互换率的动态。问题是过度识别：格子数目远大于合理的因子数，精确重现所有 SABR 微笑会破坏无套利或把远期 vol 变成不稳定的尖刺。校准必须正则化——与 <a href="/quant/calibration-regularization">校准正则化</a> 同一逻辑，对象换成远期 vol 曲线与相关结构。</p><p><span class="marginnote">术语翻译：过度识别就是「方程远多于未知数」——这里未知数是 LMM 的少数因子，方程是几百个格子的微笑，数据远多于模型自由度。硬要全部满足，只能靠扭曲参数制造噪声；正确姿势像相机对焦：主体（ATM）清晰，背景（翼部）允许糊。</span></p><p>Rebonato 的近似：互换率波动是远期波动的加权，权重冻结。于是可以把 SABR 的 ATM \\(\\alpha\\) 映射成 LMM 的瞬时 vol 函数，再尽量拟合 \\(\\rho,\\nu\\) 到因子的随机波动或位移。不能把每个格子的 \\(\\nu\\) 都当独立状态。</p><h3 id="相关结构是第一约束" tabindex="-1">相关结构是第一约束 <a class="header-anchor" href="#相关结构是第一约束" aria-label="Permalink to &quot;相关结构是第一约束&quot;">​</a></h3><p>LMM 的因子相关决定曲线形态风险（与 cap/swaption 的差）。若为了拟合翼部而让远期 vol 乱跳，相关校准会跟着重拟合噪声。顺序应是：先因子数与相关（PCA 式的曲线因子），再 ATM vol 期限结构，再微笑（SABR \\(\\rho,\\nu\\) 或随机 vol 层），每层带隔日罚。</p><p><span class="marginnote">SABR 的 \\(\\beta\\) 在利率里常取 0.5 或 0，与负利率移位耦合。\\(\\beta\\) 与移位不要同时自由，否则识别崩溃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>(1) 用历史或隐含 PCA 定 LMM 因子数与相关。(2) 用 swaption ATM 校准时间依赖的远期 vol，Rebonato 权重。(3) 用 SABR 微笑校准随机 vol 或局部位移参数，只保留少量期限依赖。(4) 检查 caplet 剥离是否在容差内，否则加 cap 权重或承认模型带。(5) 全局搜索只在低维层，局部 LM 在 vol 曲线层，见 <a href="/quant/calibration-global-opt">全局优化</a>。</p>',12)),(o(),E(A,null,{default:t(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E7%AC%AC%201%20%E5%B1%82%3A%20%E5%9B%A0%E5%AD%90%E6%95%B0%E4%B8%8E%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20S2%5B%22%E7%AC%AC%202%20%E5%B1%82%3A%20ATM%20%E8%BF%9C%E6%9C%9F%20vol%20%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E7%AC%AC%203%20%E5%B1%82%3A%20%E5%B0%91%E9%87%8F%E5%BE%AE%E7%AC%91%E5%8F%82%E6%95%B0%20%CF%81%2C%20%CE%BD%22%5D%0A%20%20S1%20--%3E%20N1%5B%22%E7%AE%A1%E6%9B%B2%E7%BA%BF%E5%BD%A2%E6%80%81%E9%A3%8E%E9%99%A9%22%5D%0A%20%20S2%20--%3E%20N2%5B%22%E7%AE%A1%E6%95%B4%E4%BD%93%E6%B0%B4%E5%B9%B3%E4%B8%8E%E6%80%BB%E6%96%B9%E5%B7%AE%22%5D%0A%20%20S3%20--%3E%20N3%5B%22%E7%AE%A1%E7%BF%BC%E9%83%A8%2C%20%E5%B8%A6%E9%9A%94%E6%97%A5%E7%BD%9A%22%5D%0A%20%20S3%20--%3E%20Hedge%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E6%98%A0%E5%9B%9E%E6%A0%BC%E5%AD%90%20SABR%20%E6%A1%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：一条 30 年美元互换曲线常有上百个远期，但 PCA 前三个因子通常解释 95% 以上的日变动。LMM 校准据此只用 3-5 个因子承载曲线动态；若某个格子 SABR 的 \\(\\nu\\) 要求专门为它开一个新因子，这层配置多半是在拟合噪声。")],-1)),a[4]||(a[4]=e("p",null,"对冲仍用市场 SABR 桶（按格子），模型内的远期 vol 敏感度要映回格子，否则交易员无法下单。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"SABR 是单标的微笑的局部参数化；LMM 是曲线的无套利动态。前者是报价坐标，后者是状态变量。校准是从坐标到状态的反问题，不适定。正则化等于承认曲线只有少数因子，微笑的 \\(\\nu\\) 是加在因子上的一层，而不是每个格子一个随机源。",-1)),(o(),E(A,null,{default:t(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Grid%5B%22Swaption%20%E6%A0%BC%E5%AD%90%20SABR%22%5D%20--%3E%20ATM%5B%22ATM%20%E6%98%A0%E5%B0%84%E5%88%B0%E8%BF%9C%E6%9C%9F%20vol%22%5D%0A%20%20PCA%5B%22%E6%9B%B2%E7%BA%BF%E5%9B%A0%E5%AD%90%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20LMM%5B%22LMM%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20ATM%20--%3E%20LMM%0A%20%20Smile%5B%22%E5%B0%91%E9%87%8F%20%CF%81%20%CE%BD%20%E5%B1%82%22%5D%20--%3E%20LMM%0A%20%20LMM%20--%3E%20Check%5B%22%E5%9B%9E%E6%A3%80%20cap%20%E4%B8%8E%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>精确拟合所有翼部会导致明天校准崩溃。现金交割 swaption、RFR 复合与历史 Libor SABR 网格不兼容。模型风险：换因子数比微调某格子 \\(\\nu\\) 对账面影响更大，应进 Cont 区间。本课不发明新的 arXiv 校准算法。</p><p><span class="marginnote">常见误区：初学者容易以为「每个格子都校得准」的模型更好。实际上格子级贴合度每提高一分，跨格子一致性就崩一分——今天每格都完美，明天远期曲线只动 2bp，全部 \\(\\alpha,\\nu\\) 重排，对冲比跟着全变。模型的价值在跨格子稳定，不在单格残差最小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>格子 SABR 是报价；LMM 是无套利动态；二者校准是正则化反问题。</li><li>先相关与 ATM，再少量微笑参数；对冲映回格子。</li><li>\\(\\beta\\) 与移位不要同时自由识别。</li><li>出处：Hagan et al., <em>Wilmott</em>, 2002；Rebonato, <em>Modern Pricing of Interest-Rate Derivatives</em>。</li></ul>',5))])}const R=B(d,[["render",m]]);export{c as __pageData,R as default};
